import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { X, Send, Check } from "lucide-react";
import { COLLECTIONS } from "./Content";

// WhatsApp SVG Icon
const WhatsAppIcon = ({ size = 20 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="white" xmlns="http://www.w3.org/2000/svg">
    <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z"/>
  </svg>
);

export default function QuoteModal({ isOpen, onClose }) {
  const [formData, setFormData] = useState({ name: "", phone: "", eventType: "", message: "" });
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    const message = `*New Quote Request - D SAJAWAT*

*Name:* ${formData.name}
*Phone:* ${formData.phone}
*Event Type:* ${formData.eventType}
*Message:* ${formData.message}`;
    window.open(`https://wa.me/919888919983?text=${encodeURIComponent(message)}`, "_blank");
    setSubmitted(true);
    setTimeout(() => {
      onClose();
      setSubmitted(false);
      setFormData({ name: "", phone: "", eventType: "", message: "" });
    }, 2000);
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-[100] flex items-center justify-center p-4"
        >
          {/* Backdrop */}
          <div
            className="absolute inset-0"
            style={{ background: "rgba(0, 0, 0, 0.5)", backdropFilter: "blur(4px)" }}
            onClick={onClose}
          />

          {/* Modal Content */}
          <motion.div
            initial={{ scale: 0.9, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            exit={{ scale: 0.9, opacity: 0 }}
            className="relative w-full max-w-lg max-h-[90vh] overflow-y-auto rounded-2xl"
            style={{ background: "#fdf8ed", border: "2px solid #d4af37" }}
          >
            {/* Close Button */}
            <button
              onClick={onClose}
              className="absolute top-4 right-4 p-2 rounded-full z-10"
              style={{ background: "rgba(255,255,255,0.8)" }}
            >
              <X size={20} color="#1a080a" />
            </button>

            {submitted ? (
              <div className="flex flex-col items-center justify-center py-12 px-6 text-center">
                <div
                  className="w-16 h-16 rounded-full flex items-center justify-center mb-4"
                  style={{ background: "rgba(212, 175, 55, 0.15)", border: "2px solid #d4af37" }}
                >
                  <Check size={32} color="#d4af37" />
                </div>
                <h3 className="serif text-2xl mb-2" style={{ color: "#1a080a" }}>Request Sent!</h3>
                <p className="text-sm" style={{ color: "rgba(26,8,10,0.6)" }}>We'll connect with you on WhatsApp shortly.</p>
              </div>
            ) : (
              <form onSubmit={handleSubmit} className="p-6">
                {/* Header */}
                <div className="mb-6 pr-8">
                  <span className="overline block mb-2">Get a Quote</span>
                  <h2 className="serif" style={{ fontSize: "clamp(24px, 5vw, 32px)", color: "#1a080a" }}>Let's decorate your event</h2>
                </div>

                {/* WhatsApp Quick Option */}
                <div className="mb-6 p-4 rounded-xl flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3" style={{ background: "rgba(37, 211, 102, 0.1)", border: "1px solid rgba(37, 211, 102, 0.3)" }}>
                  <div>
                    <p className="font-semibold text-sm" style={{ color: "#1a080a" }}>Need quick response?</p>
                    <p className="text-xs" style={{ color: "rgba(26,8,10,0.6)" }}>Chat directly on WhatsApp</p>
                  </div>
                  <a
                    href="https://wa.me/919888919983?text=Hi! I need a quick quote for D SAJAWAT fabrics"
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-2 px-4 py-2 rounded-full text-sm font-semibold text-white whitespace-nowrap"
                    style={{ background: "linear-gradient(135deg, #25d366 0%, #128c7e 100%)" }}
                  >
                    <WhatsAppIcon size={16} />Chat Now
                  </a>
                </div>

                {/* Form Fields */}
                <div className="space-y-4">
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div>
                      <label className="overline block mb-2">Your Name *</label>
                      <input
                        type="text"
                        required
                        className="field"
                        placeholder="Enter your name"
                        value={formData.name}
                        onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                      />
                    </div>
                    <div>
                      <label className="overline block mb-2">Phone *</label>
                      <input
                        type="tel"
                        required
                        className="field"
                        placeholder="Your phone number"
                        value={formData.phone}
                        onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                      />
                    </div>
                  </div>

                  <div>
                    <label className="overline block mb-2">Event Type</label>
                    <select
                      className="field"
                      value={formData.eventType}
                      onChange={(e) => setFormData({ ...formData, eventType: e.target.value })}
                    >
                      <option value="">Select event type</option>
                      <option value="Wedding">Wedding</option>
                      <option value="Corporate Event">Corporate Event</option>
                      <option value="Birthday Party">Birthday Party</option>
                      <option value="Festival">Festival</option>
                      <option value="Other">Other</option>
                    </select>
                  </div>

                  <div>
                    <label className="overline block mb-2">Your Message</label>
                    <textarea
                      className="field"
                      rows={3}
                      placeholder="Tell us about your requirements..."
                      value={formData.message}
                      onChange={(e) => setFormData({ ...formData, message: e.target.value })}
                      style={{ resize: "vertical", minHeight: 80 }}
                    />
                  </div>
                </div>

                {/* Submit Button */}
                <button type="submit" className="btn-primary w-full mt-6">
                  <Send size={18} />
                  <span>Send via WhatsApp</span>
                </button>
                <p className="text-center mt-3 text-xs" style={{ color: "rgba(26,8,10,0.5)" }}>We'll respond within 24 hours</p>
              </form>
            )}
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}
